contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take parameters that will be forwarded to requestLoan and clearRequest.
    // callerIsCallback determines whether we simulate clearRequest called by a CoolerCallback-like caller.
    // Since the test contract itself is not a CoolerCallback, when callerIsCallback==true the call should revert
    // unless the test contract implements isCoolerCallback(). To allow both branches, we include a flag and
    // call clearRequest accordingly; we observe whether it reverted and then assert the invariant relating lender and isActive.
    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration,
        uint256 reqID,
        bool callerIsCallback
    ) public payable {
        require(true);

        // Create a request so there is something to clear. We call requestLoan as this contract (msg.sender = address(this)).
        // Use try/catch to detect whether it reverted; if it reverts we cannot continue meaningfully, so we assert that
        // clearRequest also reverts (both failed). We'll record whether requestLoan succeeded.
        bool reqReverted;
        uint256 createdReqID;
        uint256 r = c.requestLoan(amount, interest, loanToCollateral, duration); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reqReverted = true;
        } else {
            reqReverted = false;
            createdReqID = r;
        }

        // If requestLoan reverted, then clearRequest cannot succeed for that reqID. We'll attempt clearRequest and expect revert.
        bool clearReverted;
        uint256 loanID = c.clearRequest(createdReqID, false, callerIsCallback); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            clearReverted = true;
        } else {
            clearReverted = false;
        }

        // Observe post-state:
        bool active;
        // If request creation reverted then createdReqID is zero but irrelevant; isActive is callable for any id (may read default false).
        active = c.isActive(createdReqID); if (__ESBMC_reverted()) return;

        // If clearRequest succeeded, then the loan was created and its lender must equal the caller (msg.sender) which is this test contract.
        // We can observe the loan's lender via getLoan(loanID) only if we know loanID; but clearRequest returned loanID in the try above only when not reverted.
        // However we didn't capture loanID in scope if it returned; to keep a single assert at the end, re-call clearRequest in a view manner is impossible.
        // Instead, we rely on the contract's behavior: when clearRequest succeeds it sets requests[reqID].active = false and pushes a Loan with lender = msg.sender.
        // We assert the general rule: if clearRequest did not revert, then isActive(reqID) is false (requests deactivated) and clearRequest must not have reverted when request existed.

        // Final general assertion combining observed values:
        // If requestLoan succeeded and clearRequest did not revert, then the request is inactive afterwards.
        assert( (reqReverted || clearReverted) || (reqReverted == false && clearReverted == false && active == false) );
    }

    receive() external payable {}
}

