// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID, bool callerIsCallback) internal {
        vm.assume(true);
        bool reqReverted;
        uint256 createdReqID;
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 r) {
            reqReverted = false;
            createdReqID = r;
        } catch {
            reqReverted = true;
        }
        bool clearReverted;
        try c.clearRequest(createdReqID, false, callerIsCallback) returns (uint256 loanID) {
            clearReverted = false;
        } catch {
            clearReverted = true;
        }
        bool active;
        try c.isActive(createdReqID) returns (bool __r) { active = __r; } catch { return; }
        assertTrue((reqReverted || clearReverted) || (reqReverted == false && clearReverted == false && active == false));
    }

    function testFuzz_run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID, bool callerIsCallback) public {
        _run(amount, interest, loanToCollateral, duration, reqID, callerIsCallback);
    }

    receive() external payable {}
}
